import{_ as o,o as l,c as n,a3 as i}from"./chunks/framework.BwzYn71E.js";const f=JSON.parse('{"title":"下线降速现象与相关补救方法探究（已被修复）","description":"","frontmatter":{"translationSource":{"title":"下线降速现象与相关补救方法探究（已被修复）","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=XnpxncxXlSmIhlbhisNQ8d","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/offline-slowdown-and-possible-remedies"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/offline-slowdown-and-possible-remedies"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/offline-slowdown-and-possible-remedies"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/offline-slowdown-and-possible-remedies"}]]},"headers":[],"relativePath":"zh/offline-slowdown-and-possible-remedies.md","filePath":"zh/page-XnpxncxXlSmIhlbhisNQ8d.md"}'),s={name:"zh/offline-slowdown-and-possible-remedies.md"};function a(t,e,d,r,p,h){return l(),n("div",null,[...e[0]||(e[0]=[i('<div class="logistics-content"><span class="logistics-source-anchor" id="下线降速现象与相关补救方法探究-已被修复" aria-hidden="true"></span><h1 id="下线降速现象与相关补救方法探究-已被修复" tabindex="-1">下线降速现象与相关补救方法探究（已被修复） <a class="header-anchor" href="#下线降速现象与相关补救方法探究-已被修复" aria-label="Permalink to &quot;下线降速现象与相关补救方法探究（已被修复）&quot;">​</a></h1><blockquote><p>源页面 ID：<code>XnpxncxXlSmIhlbhisNQ8d</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=XnpxncxXlSmIhlbhisNQ8d" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>目前已知：离线时传送带速度会发生波动，约每5分钟一次，波动总时长低于4s，离线时传送带与过滤或计数准入口疑似会同时波动。波动导致的降速结果说法较多，无法统一，疑似各人有所不同。</p><p>使传送带降为半速有时可以有效降低下线降速的影响，但疑似无法完全消除，目前无法统一结论。</p><p>目前认为当物流线上有传送带时就会因传送带速度波动而降速至传送带速。</p><p>由非群友的乾震提出可以使用差速器补电，具体为 传送带-准入口&gt;0.5-传送带，所以用传送带和准入口实现差速即可</p><p>在后续的测试中指出，汇流器在尝试汇流两条1/2占空比传送带时可能降速或阻塞物品，在减少与消除下线降速时应当注意。</p><p>部分测试结果支持传送带与准入口实际上在下线时降速相同。</p><p>部分实验结果支持非满速带可能不受下线降速影响。</p></div>',1)])])}const m=o(s,[["render",a]]);export{f as __pageData,m as default};
